  if(firstAreaElement.trim()&&firstAreaComponent.trim())captures.unshift({area:title,section:"PRIMARY ELEMENTS",element:firstAreaElement.trim(),component:firstAreaComponent.trim(),type:"",exists:"",extent:nextArea.sqm??null,extentUnit:"",remedialCost:null,remedialQuantity:null,unitRate:null,priority:"",measuredScope:"",workType:"",maintenanceWork:"",ratings:[0,0,0,0,0],comment:"",discipline:profession});
